describe('404 Page Navigation', () => {
  beforeEach(() => {
    cy.visit('/', { failOnStatusCode: false });
  });

  it('should display 404 page when navigating to invalid URL', () => {
    cy.visit('/invalid-page-that-does-not-exist', { failOnStatusCode: false });
    cy.get('h1').should('contain', '404');
    cy.get('body').should('contain', 'Page Not Found');
  });

  it('should display 404 page for deeply nested invalid routes', () => {
    cy.visit('/some/deeply/nested/invalid/route', { failOnStatusCode: false });
    cy.get('h1').should('contain', '404');
  });

  it('should have a link to return to home page from 404', () => {
    cy.visit('/nonexistent', { failOnStatusCode: false });
    cy.get('a[href="/"]').should('be.visible');
    cy.get('a[href="/"]').click();
    cy.url().should('eq', Cypress.config().baseUrl + '/');
  });

  it('should return 404 status code for invalid URL', () => {
    cy.request({ url: '/invalid-url', failOnStatusCode: false }).then((response) => {
      expect(response.status).to.equal(404);
    });
  });

  it('should handle special characters in invalid URL', () => {
    cy.visit('/page-with-@#$%', { failOnStatusCode: false });
    cy.get('h1').should('contain', '404');
  });
});
